lab.solution:
def normalize_record(record):
    title = record.get('title')
    minutes_text = record.get('minutes')
    if not isinstance(title, str) or not title.strip():
        return {'ok': False, 'error': 'title is required'}
    try:
        minutes = int(minutes_text)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'minutes must be a whole number'}
    if minutes < 0:
        return {'ok': False, 'error': 'minutes must not be negative'}
    return {'ok': True, 'value': {'title': title.strip(), 'minutes': minutes}}

lab.testCode:
assert normalize_record({'title': '  Loops ', 'minutes': '30'}) == {'ok': True, 'value': {'title': 'Loops', 'minutes': 30}}
for bad in ({'title': ' ', 'minutes': '3'}, {'title': 'Loops', 'minutes': 'two'}, {'title': 'Loops', 'minutes': '-1'}):
    assert normalize_record(bad)['ok'] is False
print('PASS: normalized row and invalid fields')
